@startuml

enum Interval {
  Weekly
  Monthly
  EveryHalfYear
  Yearly
}

enum AccessType {
  Reservable
  WalkIn
  DropOff
}

class Person {
  + LastName : string
  + FirstName : string
  + Address : string
  + PhoneNumber : string
}

abstract class PersonRole {
  + IdNumber : string
}

class Patient extends PersonRole {
  + HealthNumber : string
  + DateOfBirth : date
}

class Doctor extends PersonRole {
  + PractitionerNumber : int
  + Signature : string
}

class Requisition {
  + ValidFromDate : date
  + RepetitionCount : int
  + RepetitionInterval : Interval
}

class TestResult {
  + Result : boolean
  + Report : string
}

class SpecificTest {
  + Date : date
}

class Appointment {
  + ConfirmationNumber : string
  + Date : date
  + startTime : time
  + endTime : time
}

class BusinessHour {
  + startTime : time
  + endTime : time
}

class Lab {
  + RegistrationNumber : string
  + Name : string
  + Address : string
  + ChangeCancelFee : float
}

class Test {
  + Name : string
  + Duration : string
}

class TestType {
  + Name : string
  + Access : AccessType
}

Person "1" -- "*" PersonRole

Patient "1" -- "*" Requisition : has
Doctor "1" -- "*" Requisition : prescribes

Requisition "1" -- "1..*" SpecificTest : contains

SpecificTest "0..1" -- "1" TestResult : has result

SpecificTest "*" -- "1" Test : is a type of
Test "*" -- "1" TestType : categorized by

Patient "0..1" -- "*" Appointment : makes
Requisition "0..1" -- "0..1" Appointment : for
Appointment "*" -- "1" Lab : at

Lab "1" -- "*" BusinessHour : has
Lab "1" -- "*" Test : offers

@enduml

